uid_t R_ID = 0;   // Real ID
uid_t E_ID = 1000; // Effective ID
uid_t S_ID = 500; // Saved Set-UID

// Set all three IDs (requires privilege if R/E/S != current EUID)
int status1 = setresuid(R_ID, E_ID, S_ID);

// Drop EID to 1000, keeping RUID/SUID unchanged (-1)
int status2 = setresuid(-1, 1000, -1);

// Permanently drop all privileges to user 1000
// RUID, EUID, SUID all set to the same unprivileged ID
setresuid(1000, 1000, 1000);

// Use -1 for error status check (0 on success)
if (status1 == -1) { /* handle error */ }
